from collections import Counter

def findSubstring(self, s: str, words: list[str]) -> list[int]:
    if not words:
        return []
    L = len(words[0])
    k = len(words)
    total = k * L
    res: list[int] = []
    if len(s) < total:
        return res
    need = Counter(words)
    for i in range(len(s) - total + 1):
        seen: dict[str, int] = {}
        j = 0
        while j < k:
            start = i + j * L
            word = s[start:start + L]
            if word not in need:
                break
            seen[word] = seen.get(word, 0) + 1
            if seen[word] > need[word]:
                break
            j += 1
        if j == k:
            res.append(i)
    return res

code.java:
public List<Integer> findSubstring(String s, String[] words) {
    List<Integer> res = new ArrayList<>();
    int k = words.length;
    if (k == 0) return res;
    int L = words[0].length();
    int total = k * L;
    if (s.length() < total) return res;
    Map<String, Integer> need = new HashMap<>();
    for (String w : words) need.merge(w, 1, Integer::sum);
    for (int offset = 0; offset < L; offset++) {
        int left = offset, count = 0;
        Map<String, Integer> window = new HashMap<>();
        for (int right = offset; right + L <= s.length(); right += L) {
            String word = s.substring(right, right + L);
            if (need.containsKey(word)) {
                window.merge(word, 1, Integer::sum);
                count++;
                while (window.get(word) > need.get(word)) {
                    String leftWord = s.substring(left, left + L);
                    window.merge(leftWord, -1, Integer::sum);
                    left += L;
                    count--;
                }
                if (count == k) {
                    res.add(left);
                    String leftWord = s.substring(left, left + L);
                    window.merge(leftWord, -1, Integer::sum);
                    left += L;
                    count--;
                }
            } else {
                window.clear();
                count = 0;
                left = right + L;
            }
        }
    }
    return res;
}

